"use client";

import * as React from "react";
import * as DropdownMenuPrimitive from "@radix-ui/react-dropdown-menu";
import { Check, ChevronRight, Circle } from "lucide-react";
import { cn } from "@/lib/utils";
import { withDirectionalPortal } from "@/components/ui/direction-provider";

const DropdownMenu = DropdownMenuPrimitive.Root;
const DropdownMenuTrigger = DropdownMenuPrimitive.Trigger;
const DropdownMenuGroup = DropdownMenuPrimitive.Group;
const DropdownMenuPortal = withDirectionalPortal(DropdownMenuPrimitive.Portal);
const DropdownMenuSub = DropdownMenuPrimitive.Sub;
const DropdownMenuRadioGroup = DropdownMenuPrimitive.RadioGroup;

const contentCls =
    // Capped to the room Radix reports it has, so large text cannot push the surface past the window —
    // see the note in popover.tsx for the measurement that prompted it.
    // `min-w` yields to the available room, which is not a detail: `min-width` beats `max-width` in CSS,
    // so the cap above was unenforceable on its own. Measured on a 390px phone with the root font size
    // doubled — 8rem becomes 256px, the cap resolved to 193px, and the menu came out 256px wide with its
    // right edge 63px past the window and those items unreachable. `min(...)` keeps the comfortable
    // minimum whenever there is room for it and gives it up when there is not.
  "z-overlay max-w-[var(--radix-popper-available-width)] min-w-[min(8rem,var(--radix-popper-available-width))] overflow-hidden rounded-md border bg-popover p-1 text-popover-foreground shadow-md font-sans data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=open]:duration-fast data-[state=open]:ease-enter data-[state=closed]:duration-instant data-[state=closed]:ease-exit";
const itemCls =
  "relative flex cursor-default select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none transition-colors focus:bg-accent focus:text-accent-foreground focus:ring-1 focus:ring-inset focus:ring-ring data-[disabled]:pointer-events-none data-[disabled]:opacity-disabled";

const DropdownMenuContent = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Content>
>(({ className, sideOffset = 4, ...props }, ref) => (
  <DropdownMenuPortal>
    <DropdownMenuPrimitive.Content ref={ref} sideOffset={sideOffset} className={cn(contentCls, className)} {...props} />
  </DropdownMenuPortal>
));
DropdownMenuContent.displayName = DropdownMenuPrimitive.Content.displayName;

const DropdownMenuItem = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Item> & { inset?: boolean }
>(({ className, inset, ...props }, ref) => (
  <DropdownMenuPrimitive.Item ref={ref} className={cn(itemCls, inset && "ps-8", className)} {...props} />
));
DropdownMenuItem.displayName = DropdownMenuPrimitive.Item.displayName;

const DropdownMenuCheckboxItem = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.CheckboxItem>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.CheckboxItem>
>(({ className, children, checked, ...props }, ref) => (
  <DropdownMenuPrimitive.CheckboxItem ref={ref} className={cn(itemCls, "ps-8", className)} checked={checked} {...props}>
    <span className="absolute start-2 flex size-3.5 items-center justify-center">
      <DropdownMenuPrimitive.ItemIndicator>
        <Check className="size-4" />
      </DropdownMenuPrimitive.ItemIndicator>
    </span>
    {children}
  </DropdownMenuPrimitive.CheckboxItem>
));
DropdownMenuCheckboxItem.displayName = DropdownMenuPrimitive.CheckboxItem.displayName;

const DropdownMenuRadioItem = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.RadioItem>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.RadioItem>
>(({ className, children, ...props }, ref) => (
  <DropdownMenuPrimitive.RadioItem ref={ref} className={cn(itemCls, "ps-8", className)} {...props}>
    <span className="absolute start-2 flex size-3.5 items-center justify-center">
      <DropdownMenuPrimitive.ItemIndicator>
        <Circle className="size-2 fill-current" />
      </DropdownMenuPrimitive.ItemIndicator>
    </span>
    {children}
  </DropdownMenuPrimitive.RadioItem>
));
DropdownMenuRadioItem.displayName = DropdownMenuPrimitive.RadioItem.displayName;

const DropdownMenuLabel = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Label>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Label> & { inset?: boolean }
>(({ className, inset, ...props }, ref) => (
  <DropdownMenuPrimitive.Label
    ref={ref}
    className={cn("px-2 py-1.5 text-sm font-semibold", inset && "ps-8", className)}
    {...props}
  />
));
DropdownMenuLabel.displayName = DropdownMenuPrimitive.Label.displayName;

const DropdownMenuSeparator = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Separator>
>(({ className, ...props }, ref) => (
  <DropdownMenuPrimitive.Separator ref={ref} className={cn("-mx-1 my-1 h-px bg-muted", className)} {...props} />
));
DropdownMenuSeparator.displayName = DropdownMenuPrimitive.Separator.displayName;

// opacity-60 (not --opacity-muted's 0.7) is a pre-existing inconsistency —
// left as a literal rather than silently changing the rendered value.
const DropdownMenuShortcut = ({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) => (
  <span className={cn("ms-auto text-xs tracking-widest opacity-60", className)} {...props} />
);
DropdownMenuShortcut.displayName = "DropdownMenuShortcut";

const DropdownMenuSubTrigger = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.SubTrigger>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.SubTrigger> & { inset?: boolean }
>(({ className, inset, children, ...props }, ref) => (
  <DropdownMenuPrimitive.SubTrigger
    ref={ref}
    className={cn(itemCls, "data-[state=open]:bg-accent", inset && "ps-8", className)}
    {...props}
  >
    {children}
    <ChevronRight className="ms-auto size-4 rtl:-scale-x-100" />
  </DropdownMenuPrimitive.SubTrigger>
));
DropdownMenuSubTrigger.displayName = DropdownMenuPrimitive.SubTrigger.displayName;

const DropdownMenuSubContent = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.SubContent>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.SubContent>
>(({ className, ...props }, ref) => (
  <DropdownMenuPrimitive.SubContent ref={ref} className={cn(contentCls, className)} {...props} />
));
DropdownMenuSubContent.displayName = DropdownMenuPrimitive.SubContent.displayName;

export {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuCheckboxItem,
  DropdownMenuRadioItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuGroup,
  DropdownMenuPortal,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuRadioGroup,
};

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened AND left the keyboard stranded — so a handler
 * that removes nothing, or that moves focus somewhere of its own, keeps the focus it chose.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    // And step in only where the removal actually stranded the keyboard. A handler that moved focus
    // somewhere of its own — the input a chip group is typed into, say — made a deliberate choice,
    // and that choice wins. Stranded means focus fell back to the document, which is what a browser
    // does when the focused element is taken out of the tree.
    const doc = trigger.ownerDocument;
    const active = doc.activeElement;
    const stranded = !active || active === doc.body || active === doc.documentElement || !active.isConnected;
    if (!stranded) return true;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
